# SERVICE & SACRIFICE BANNER - two versions, nothing saved
$spent = 0.0
$bn = 'A wide panoramic header banner for the "Service & Sacrifice" category of a tattoo website. On the right half, a real action photograph of two military warriors in motion, framed from the waist up so they fill the full height of the photo and their tattoos are large, sharp and easy to read: a huge bearded man in his thirties, muscular and battle-hardened, in a sleeveless olive tank top, striding forward hard with a fierce stare, his whole arm covered in a black-and-grey military tattoo of a screaming eagle, a waving flag and a skull in a helmet; beside him a fit woman in her thirties with her hair pulled back tight, in a black sleeveless top, moving forward fast with a fierce, determined look, her strong forearm carrying a bold black-and-grey tattoo of an anchor wrapped in a flowing flag ribbon. Behind them, drifting smoke, dust and a blurred American flag. On the left half, on a dark smoky background, the words "Service & Sacrifice" written large in bold military stencil lettering in worn steel and gold, surrounded by warrior tattoo art - a bald eagle with spread wings, crossed rifles, dog tags on a chain, an anchor, pilot wings and a helicopter silhouette. The art fades into the photo through smoke and sparks. Intense, powerful and cinematic, high detail. Only the words "Service & Sacrifice", no other text, no watermark, no logos.'
$body = @{ subject=$bn; model="gpt-image-2"; width=2048; height=768; exact_size=$true; raw=$true } | ConvertTo-Json -Compress
try { $j = (RUN ("SHOW_IT " + $body)) | ConvertFrom-Json
  if ($j.payload.ok -and $j.payload.id) { $spent += [double]$j.payload.cost_usd; "  BANNER A -> " + $j.payload.image_url } else { "  BANNER A -> NOT DRAWN: " + $j.payload.error } } catch { "  BANNER A -> NOT DRAWN: " + $_.Exception.Message }
